message.content:
{
  "qid": "0002-FFTCG-L2-01",
  "sample_id": "0002",
  "gen_prompt": "请绘制一张白色背景下的《最终幻想》集换式卡牌展示拼贴：八张，两行四列排列。",
  "invocation": "L2",
  "knowledge_dim": "最终幻想集换式卡牌的实体商品形态、卡面信息结构与IP识别规范",
  "fidelity_checks": [
    {
      "check": "画面主体必须呈现《最终幻想》集换式卡牌的实体纸面商品或可识别卡牌展示，而不是电子游戏截图、普通周边或抽象海报。",
      "anchor": {
        "type": "combination",
        "constraint_refs": ["1"],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "主体为电子游戏画面、普通周边、海报或完全无法看出实体纸面商品。",
        "tier_1": "画面中存在纸面商品元素，但卡牌或卡牌展示不占主导，只能勉强看出与卡牌商品有关。",
        "tier_2": "画面主导区域清晰呈现多张实体卡牌或卡牌展示拼贴，可明确识别为实体纸面商品。"
      },
      "variants_used": "多张卡牌或对战牌面",
      "visibility_requirement": "若边缘裁切，只要主体区域满足实体卡牌展示即可；完全无实体纸面商品时按0分。",
      "weight": 1.0
    },
    {
      "check": "若画面露出单张卡牌，卡牌外形必须是竖向矩形的印刷卡牌形态。",
      "anchor": {
        "type": "combination",
        "constraint_refs": ["2"],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "露出的单张卡牌为横向矩形、正方形、异形，或完全没有印刷卡牌形态。",
        "tier_1": "部分露出卡牌接近竖向矩形，但比例明显失真、边缘变形，或仅局部可见难以确认。",
        "tier_2": "所有露出的单张卡牌均为竖向矩形印刷卡牌形态，比例合理且边缘清晰。"
      },
      "variants_used": "无",
      "visibility_requirement": "若画面完全没有露出任何单张卡牌，仅显示包装、卡背或被整体遮挡，本条视为满分。",
      "weight": 1.0
    },
    {
      "check": "所有可见卡面插画主题必须属于最终幻想系列自身IP内容，可在历代角色、召唤兽、怪物、经典场景、元素水晶/属性符号、陆行鸟/莫古利等合法变体中呈现。",
      "anchor": {
        "type": "combination",
        "constraint_refs": ["3"],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "主要可见卡面插画为其他IP专属形象，或与最终幻想系列无关的原创奇幻内容。",
        "tier_1": "部分卡面插画可归入最终幻想IP，部分为无关内容或无法确认。",
        "tier_2": "所有可见卡面插画均可归入最终幻想IP合法变体；未指定具体角色时，任意合法变体均可。"
      },
      "variants_used": "系列历代角色 / 召唤兽 / 怪物 / 经典场景 / 元素水晶/属性符号 / 陆行鸟/莫古利",
      "visibility_requirement": "若卡面插画完全被遮挡，本条视为满分；若部分遮挡，按可见部分判定。",
      "weight": 1.0
    },
    {
      "check": "若卡牌正面可见，卡面必须包含游戏信息要素中的至少若干项：卡名、元素水晶图标、费用或数值、卡牌类型、效果文本。",
      "anchor": {
        "type": "combination",
        "constraint_refs": ["4"],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "正面卡面几乎只有插画，缺少可辨游戏信息。",
        "tier_1": "可见1至2项游戏信息，或信息存在但过小、过糊、难以确认。",
        "tier_2": "可见至少3项游戏信息，且能对应标准边框、全幅插画、闪卡或促销卡等合法卡面变体。"
      },
      "variants_used": "标准边框卡面 / 全幅插画卡面 / 闪卡或促销卡面",
      "visibility_requirement": "若画面仅露出卡背或包装，本条视为满分；若正面可见但文字不可读，按信息要素数量判定。",
      "weight": 1.0
    },
    {
      "check": "画面必须具有可将其识别为Final Fantasy TCG的视觉标识，例如包装或卡背上的FINAL FANTASY TRADING CARD GAME标志，或卡面底部可辨的版权/系列标识。",
      "anchor": {
        "type": "combination",
        "constraint_refs": ["5"],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "没有任何可识别为Final Fantasy TCG的文字标志、系列标识或版权信息。",
        "tier_1": "有模糊文字、局部logo或版权痕迹，但不足以确认是该TCG。",
        "tier_2": "清晰可见可识别的Final Fantasy TCG标志、包装/卡背标识或底部版权/系列标识。"
      },
      "variants_used": "无",
      "visibility_requirement": "若构图未露出任何标识区域，本条按0分；若标识被部分裁切但仍可辨认，按及格或满分。",
      "weight": 1.0
    },
    {
      "check": "画面不得出现最终幻想系列以外的其他IP专属角色或怪物形象，例如宝可梦、游戏王等其他卡牌游戏形象。",
      "anchor": {
        "type": "combination",
        "constraint_refs": ["6"],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "画面中出现可辨认的其他IP专属角色、怪物或卡牌形象。",
        "tier_1": "出现高度相似但无法确认是否属于其他IP的形象。",
        "tier_2": "画面中没有任何可辨认的其他IP专属角色或怪物形象。"
      },
      "variants_used": "无",
      "visibility_requirement": "任何可辨认区域出现其他IP专属形象即0分；若因模糊无法辨认按及格。",
      "weight": 1.0
    }
  ],
  "alignment_checks": [
    {
      "check": "背景为纯白色。",
      "facet": "real_world_scene",
      "rubric": {
        "tier_0": "背景不是白色，或为复杂场景。",
        "tier_1": "背景接近白色但有明显灰调、色偏或干扰元素。",
        "tier_2": "背景为纯白或接近纯白，无干扰场景。"
      }
    },
    {
      "check": "画面中有八张卡牌。",
      "facet": "quantity",
      "rubric": {
        "tier_0": "数量明显不是八张。",
        "tier_1": "数量为七张或九张，或部分遮挡导致难以准确计数。",
        "tier_2": "清晰可见八张卡牌。"
      }
    },
    {
      "check": "八张卡牌呈两行四列排列。",
      "facet": "spatial_2d",
      "rubric": {
        "tier_0": "没有两行四列结构。",
        "tier_1": "近似网格排列，但行列数错误或明显错位。",
        "tier_2": "清晰呈现两行四列排列。"
      }
    }
  ],
  "quality_facets": [
    "material_texture",
    "edge_clarity",
    "resolution"
  ],
  "aesthetic_facets": [
    "composition",
    "color_harmony",
    "lighting_atmosphere"
  ],
  "leak_check": {
    "对照表": [
      {
        "constraint_ref": "1",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "2",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "3",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "4",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "5",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "6",
        "题面中是否出现": "无"
      }
    ],
    "结论": "全为无"
  },
  "notes": "题面仅点名概念与场景、数量、排列，未出现竖向矩形、卡名、元素水晶、FINAL FANTASY TRADING CARD GAME、其他IP等约束关键词；样本图中的SAMPLE水印不作为判分依据。"
}
